import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Qvwhmedc.js";var i=JSON.parse(`{"title":"Setup - Legacy (Ember)","description":"","frontmatter":{"title":"Setup - Legacy (Ember)"},"headers":[],"relativePath":"guides/configuration/ember.md","filePath":"guides/configuration/ember.md"}`),a={name:`guides/configuration/ember.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<div class="warning custom-block"><p class="custom-block-title">caution</p><p>Older legacy features of WarpDrive (inherited from when the library was named EmberData) should only be used with Ember.</p></div><h1 id="legacy-feature-setup-for-ember-apps" tabindex="-1">Legacy Feature Setup for Ember Apps <a class="header-anchor" href="#legacy-feature-setup-for-ember-apps" aria-label="Permalink to “Legacy Feature Setup for Ember Apps”">​</a></h1><h2 id="configuring-typescript" tabindex="-1">Configuring TypeScript <a class="header-anchor" href="#configuring-typescript" aria-label="Permalink to “Configuring TypeScript”">​</a></h2><p>TypeScript will automatically discover the types these packages provide. If you&#39;re using <code>ember-source</code>, you should also configure and use Ember&#39;s native types. If you previously had any <a href="https://github.com/DefinitelyTyped/DefinitelyTyped" target="_blank" rel="noreferrer">DefinitelyTyped (@types)</a> packages installed for ember or ember-data you should remove those.</p><p>If you have any references to ember-data or warp-drive types or types packages in package.json or tsconfig.json you can remove those.</p><h2 id="what-is-legacy" tabindex="-1">What is &quot;Legacy&quot; <a class="header-anchor" href="#what-is-legacy" aria-label="Permalink to “What is &quot;Legacy&quot;”">​</a></h2><p>You&#39;ve probably heard old code patterns referred to as &quot;legacy code&quot; before. In WarpDrive, Legacy refers to older features to which we are giving a second, extended life. When features are deprecated in <code>@warp-drive/core</code>, they are added to <code>@warp-drive/legacy</code> in a way that allows apps to opt-in to bring them back.</p><p>Legacy features will not live forever, but they will receive a second deprecation cycle before being deleted. There is no set schedule to when code in legacy might be deprecated. Sometimes it may become deprecated immediately after the feature is removed from core, other times it may last for several majors. Occasionally a deprecation in core won&#39;t be able to be restored from legacy at all. It all depends on how easy the feature is to maintain support for weighed against the community and maintenance costs of keeping it around.</p><p>For example, if Ember were to deprecated EmberObject, then maintaining support for Model, Adapter and Serializer would become untenable quickly - so we would opt to simultaneously deprecate these from legacy.</p><p>The <code>@warp-drive/legacy</code> package is opt-in. New apps should not use it, existing apps should work to remove the features it provides. Consider it your cleanup checklist.</p><h2 id="restoring-emberobject-features" tabindex="-1">Restoring EmberObject Features <a class="header-anchor" href="#restoring-emberobject-features" aria-label="Permalink to “Restoring EmberObject Features”">​</a></h2><ul><li>use per-trait or per-resource or per-field extension</li></ul><h2 id="restoring-ember-arraylike-features" tabindex="-1">Restoring Ember ArrayLike Features <a class="header-anchor" href="#restoring-ember-arraylike-features" aria-label="Permalink to “Restoring Ember ArrayLike Features”">​</a></h2><ul><li>use per-field extension</li></ul><h2 id="adapter-serializer-and-legacy-request-methods" tabindex="-1">Adapter/Serializer and Legacy Request Methods <a class="header-anchor" href="#adapter-serializer-and-legacy-request-methods" aria-label="Permalink to “Adapter/Serializer and Legacy Request Methods”">​</a></h2><p>You should configure support for legacy requests if your application still makes requests which use an Adapter or Serializer.</p><p>Some example APIs you may still be using that are reasons to configure this legacy support include:</p><ul><li>You have async relationships that don&#39;t yet have links</li><li>You have sync relationships that you load via references that don&#39;t yet have links</li><li>You still use methods on the store to fetch data other than <code>store.request</code></li><li>You still fetch data with the Legacy builders</li><li>You still use <code>model.save</code> or <code>model.destroyRecord</code></li></ul><p>You may also find you want to use Legacy Requests if you are creating a new application and <a href="./../the-manual/misc/links-mode">LinksMode</a> is not sufficient</p><ul><li>add the LegacyNetworkHandler</li><li>add the Legacy Request APIs back</li><li>add the adapterFor, serializerFor, modelFor, pushPayload, and normalize hooks back</li><li>caveat: serialization/normalization of newer field schemas</li></ul><h2 id="model" tabindex="-1">Model <a class="header-anchor" href="#model" aria-label="Permalink to “Model”">​</a></h2><ul><li>custom extensions</li></ul><h2 id="modelfragments" tabindex="-1">ModelFragments <a class="header-anchor" href="#modelfragments" aria-label="Permalink to “ModelFragments”">​</a></h2><h2 id="other" tabindex="-1">Other <a class="header-anchor" href="#other" aria-label="Permalink to “Other”">​</a></h2><ul><li>resetOnRemote</li><li>filterDuplicates</li></ul>`,25)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};